        return false;
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k;
        freq[rem]++;
    }
    if (freq[0] % 2 != 0) {
        return false;
    }
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) { // k even and r == k/2
            if (freq[r] % 2 != 0) {
