                return false;
            }
        }
    }
    return true;
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    int[] freq = new int[26];
    for (char ch : s.toCharArray()) {
        if (ch >= 'a' && ch <= 'z') {
            freq[ch - 'a']++;
        } else {
            // If characters outside 'a'-'z' are present, treat them separately
            // by expanding the frequency array to cover all ASCII characters.
            // For simplicity, we return the original string in such cases.
            return s;
        }
    }
    StringBuilder result = new StringBuilder();
    int total = s.length();
    while (result.length() < total) {
        // Ascending pass
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
            }
        }
        // Descending pass
        for (int i = 25; i >= 0; i--) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
            }
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) {
        return false;
    }
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    // dp[k] holds all possible sums using exactly k elements
    @SuppressWarnings("unchecked")
    Set<Integer>[] dp = new Set[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = new HashSet<>();
    }
    dp[0].add(0);
    for (int num : nums) {
        for (int k = n - 1; k >= 1; k--) {
            for (int prevSum : dp[k - 1]) {
                dp[k].add(prevSum + num);
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        long product = (long) totalSum * k;
        if (product % n != 0) {
            continue;
        }
        int target = (int) (product / n);
        if (dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    // dp[i] represents the minimum cost to reach step i
    // We only need the last two values at any time
    int prev2 = 0; // dp[0]
    int prev1 = 0; // dp[1]
    for (int i = 2; i <= n; i++) {
        int costFromPrev1 = prev1 + cost[i - 1];
        int costFromPrev2 = prev2 + cost[i - 2];
        int current = Math.min(costFromPrev1, costFromPrev2);
        prev2 = prev1;
        prev1 = current;
    }
    return prev1;
}

