public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int maxSum = Integer.MIN_VALUE;
    int minSum = Integer.MAX_VALUE;
    int currentMax = 0;
    int currentMin = 0;
    for (int num : nums) {
        currentMax = Math.max(num, currentMax + num);
        maxSum = Math.max(maxSum, currentMax);
        currentMin = Math.min(num, currentMin + num);
        minSum = Math.min(minSum, currentMin);
    }
    return Math.max(maxSum, -minSum);
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0; // No positive Fibonacci numbers needed for non‑positive k
    }

    // Generate all Fibonacci numbers up to k
    java.util.List<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1);
    fibs.add(1);
    while (true) {
        int sz = fibs.size();
        int next = fibs.get(sz - 1) + fibs.get(sz - 2);
        if (next > k) {
            break;
        }
        fibs.add(next);
    }

    int count = 0;
    int remaining = k;

    // Greedy: subtract the largest Fibonacci number <= remaining
    for (int i = fibs.size() - 1; i >= 0 && remaining > 0; i--) {
        int f = fibs.get(i);
        if (f <= remaining) {
            remaining -= f;
            count++;
        }
    }

    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.ArrayList<Integer> factors = new java.util.ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            factors.add(i);
            int other = n / i;
            if (other != i) {
                factors.add(other);
            }
        }
    }
    java.util.Collections.sort(factors);
    if (factors.size() < k) {
        return -1;
    }
    return factors.get(k - 1);
}

public String makeGood(String s) {
