    }
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char current = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char last = stack.charAt(len - 1);
            // Check if current and last are the same letter with opposite cases
            if (Math.abs(current - last) == 32) {
                stack.deleteCharAt(len - 1); // remove the pair
                continue;
            }
        }
        stack.append(current);
    }
    return stack.toString();
}

public class MaxUniqueSplit {
    public int maxUniqueSplit(String s) {
        if (s == null || s.isEmpty()) {
            return 0;
        }
        int[] max = new int[1];
        backtrack(s, 0, new java.util.HashSet<>(), 0, max);
        return max[0];
    }

    private void backtrack(String s, int index, java.util.Set<String> used, int count, int[] max) {
        if (index == s.length()) {
            if (count > max[0]) {
                max[0] = count;
            }
            return;
        }
        for (int end = index + 1; end <= s.length(); end++) {
            String sub = s.substring(index, end);
            if (!used.contains(sub)) {
                used.add(sub);
                backtrack(s, end, used, count + 1, max);
                used.remove(sub);
            }
        }
    }
}

