}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][] horiz = new int[m][n];
    int[][] vert = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] anti = new int[m][n];
    int maxLen = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horiz[i][j] = (j > 0 ? horiz[i][j - 1] : 0) + 1;
                vert[i][j] = (i > 0 ? vert[i - 1][j] : 0) + 1;
                diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                anti[i][j] = (i > 0 && j < n - 1 ? anti[i - 1][j + 1] : 0) + 1;
                int localMax = Math.max(Math.max(horiz[i][j], vert[i][j]),
                                        Math.max(diag[i][j], anti[i][j]));
                if (localMax > maxLen) {
                    maxLen = localMax;
                }
            }
        }
    }
    return maxLen;
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    boolean negative = n < 0;
    long absValue = Math.abs((long) n);
    StringBuilder sb = new StringBuilder();
    int digitCount = 0;
    while (absValue > 0) {
        sb.append(absValue % 10);
        absValue /= 10;
        digitCount++;
        if (absValue > 0 && digitCount % 3 == 0) {
            sb.append('.');
        }
    }
    if (negative) {
        sb.append('-');
    }
    return sb.reverse().toString();
}

