public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    String s = String.valueOf(n);
    int len = s.length();
    int[] digits = new int[len];
    for (int i = 0; i < len; i++) {
        digits[i] = s.charAt(i) - '0';
    }

    // Find the rightmost index i where digits[i] < digits[i+1]
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        // No higher permutation exists
        return -1;
    }

    // Find the rightmost index j > i where digits[j] > digits[i]
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap digits[i] and digits[j]
    int temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the subarray from i+1 to end
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }

    // Build the resulting number
    long result = 0;
    for (int d : digits) {
        result = result * 10 + d;
        if (result > Integer.MAX_VALUE) {
            return -1;
        }
    }

    return (int) result;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    result = buildStrobogrammatic(n, n);
    return result;
}

private static List<String> buildStrobogrammatic(int currentLen, int totalLen) {
    List<String> res = new ArrayList<>();
    if (currentLen == 0) {
        res.add("");
        return res;
    }
    if (currentLen == 1) {
        res.add("0");
        res.add("1");
        res.add("8");
        return res;
    }
    List<String> middles = buildStrobogrammatic(currentLen - 2, totalLen);
    for (String middle : middles) {
        if (currentLen != totalLen) {
            res.add("0" + middle + "0");
        }
        res.add("1" + middle + "1");
        res.add("6" + middle + "9");
        res.add("8" + middle + "8");
        res.add("9" + middle + "6");
    }
    return res;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    // Check for duplicate points
    for (int i = 0; i < 3; i++) {
        for (int j = i + 1; j < 3; j++) {
            if (points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
                return false;
            }
        }
    }
    // Compute cross product to check collinearity
    long x1 = points[0][0], y1 = points[0][1];
    long x2 = points[1][0], y2 = points[1][1];
    long x3 = points[2][0], y3 = points[2][1];
    long cross = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);
    return cross != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer.");
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int maxLen = 1;
    int currentLen = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLen++;
        } else {
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
            currentLen = 1;
        }
    }
    return Math.max(maxLen, currentLen);
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    long cur = 1;
    while (cur <= n) {
        result.add((int) cur);
        if (cur * 10 <= n) {
            cur *= 10;
        } else {
            while (cur % 10 == 9 || cur + 1 > n) {
                cur /= 10;
            }
            cur++;
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : nums) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < min) {
                min = candidate;
            }
        }
        dp[i] = min;
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    int wordStart = 0;
    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == ' ') {
            // Reverse the word before the space
            result.append(new StringBuilder(s.substring(wordStart, i)).reverse());
            result.append(' ');
            wordStart = i + 1;
        }
    }
    // Reverse the last word (or the whole string if no spaces)
    result.append(new StringBuilder(s.substring(wordStart)).reverse());
    return result.toString();
}
